Our ad campaign form (react-hook-form + zod) has a bug: the "max budget must be at least min budget" error shows up weirdly, sometimes only after the other field errors are fixed. Here's the schema and the submit handler. We also have `CAMPAIGN_NAME_MIN` (3) and `CAMPAIGN_NAME_MAX` (60) exported from `constraints/campaign.ts`, in case that matters.

```ts
export const campaignSchema = z
  .object({
    name: z
      .string()
      .min(3, 'Name must be at least 3 characters')
      .max(60, 'Name must be at most 60 characters'),
    budgetMin: z.coerce.number().positive(),
    budgetMax: z.coerce.number().positive(),
  })
  .transform((v, ctx) => {
    if (v.budgetMax < v.budgetMin) {
      ctx.addIssue({
        code: 'custom',
        path: ['budgetMax'],
        message: 'Max budget must be at least min budget',
      });
      return z.NEVER;
    }
    return v;
  });

const onSubmit = async (data: CampaignForm) => {
  if (data.name.toLowerCase().includes('test')) {
    setError('name', { message: 'Name cannot contain "test"' });
    return;
  }
  await createCampaign(data);
};
```

