Refund dialog for support agents. Works but the code reviewer hates it. Can you clean up the validation and typing? Constants already exist in `constants/refund.ts`: `REFUND_REASON_MIN = 10`, `REFUND_REASON_MAX = 300`. The form hook call (react-hook-form, no resolver at all right now) has no type argument. `Order` type is in `types/order.ts` and has `id`, `total`.

```tsx
export function RefundForm({ order, onDone }: { order: any; onDone: () => void }) {
  // ...form hook called here, untyped
  const submit = async (data: any) => {
    if (!data.reason || data.reason.length < 10) {
      setError('reason', { message: 'Reason must be at least 10 characters' });
      return;
    }
    if (data.reason.length > 300) {
      setError('reason', { message: 'Reason must be under 300 characters' });
      return;
    }
    if (Number(data.amount) <= 0) {
      setError('amount', { message: 'Amount must be positive' });
      return;
    }
    if (Number(data.amount) > order.total) {
      setError('amount', { message: 'Refund cannot exceed order total' });
      return;
    }
    await api.refund(order.id, data);
    onDone();
  };
  // JSX omitted
}
```

